add_filter( 'custom_menu_order', '__return_true' );
add_filter( 'menu_order', 'perfectpixel_reorder_admin_menu', 999 );

function perfectpixel_reorder_admin_menu( $menu_order ) {
	if ( ! is_array( $menu_order ) ) {
		return $menu_order;
	}
	$wanted = array_filter( array_map( 'trim', explode( ',', '{{admin_menu_order}}' ) ) );
	$first  = array();
	foreach ( $wanted as $slug ) {
		if ( in_array( $slug, $menu_order, true ) && ! in_array( $slug, $first, true ) ) {
			$first[] = $slug;
		}
	}
	return array_merge( $first, array_values( array_diff( $menu_order, $first ) ) );
}
